import { describe, expect, it } from "vitest";
import { createHash } from "juava";
import { deps, seedWorkspace } from "./support/harness";
import { AuthChecker } from "../../lib/server/mcp-server/auth";
import { OAuthHandlers } from "../../lib/server/mcp-server/oauth";

// No origin stub: send401 builds the WWW-Authenticate metadata URL from
// getPublicOrigin(), which reads JITSU_PUBLIC_URL at call time — the harness
// baseline env (http://console.test.local) covers it. Token rows are real
// UserApiToken records in the per-file database.

const noopSchedule = (_fn: () => Promise<any>) => {};

function makeReq(authorization: string) {
  return { headers: { authorization } } as any;
}

function makePostReq(body: any) {
  return { method: "POST", headers: {}, socket: {}, body } as any;
}

function makeRes() {
  const res: any = {
    statusCode: 200,
    body: undefined,
    headers: {} as Record<string, any>,
    setHeader(name: string, value: any) {
      this.headers[name] = value;
    },
    status(code: number) {
      this.statusCode = code;
      return this;
    },
    json(payload: any) {
      this.body = payload;
      return this;
    },
  };
  return res;
}

async function seedApiKey(opts: { secret: string; oauthClientId?: string }) {
  const { prisma } = deps();
  const { user } = await seedWorkspace();
  let oauthClientId: string | undefined;
  if (opts.oauthClientId) {
    const client = await prisma.oAuthClient.create({
      data: { clientSecretHash: createHash("client-secret"), name: "test client", redirectUris: [] },
    });
    oauthClientId = client.id;
  }
  const token = await prisma.userApiToken.create({
    data: {
      hint: opts.secret.slice(0, 3) + "***",
      hash: createHash(opts.secret),
      userId: user.internalId,
      ...(oauthClientId ? { oauthClientId } : {}),
    },
  });
  return { token, user };
}

describe("AuthChecker: MCP auth via personal API key", () => {
  it("authenticates a personal key (oauthClientId null)", async () => {
    const secret = "keysecret";
    const { token, user } = await seedApiKey({ secret });
    const auth = await new AuthChecker(deps().prisma, noopSchedule).requireAccessToken(
      makeReq(`Bearer ${token.id}:${secret}`),
      makeRes()
    );
    expect(auth?.extra?.userId).toBe(user.internalId);
    expect(auth?.clientId).toBe("api-key");
  });

  it("rejects an OAuth refresh token (oauthClientId set) presented as a key", async () => {
    const secret = "refreshsecret";
    const { token } = await seedApiKey({ secret, oauthClientId: "yes" });
    const res = makeRes();
    const auth = await new AuthChecker(deps().prisma, noopSchedule).requireAccessToken(
      makeReq(`Bearer ${token.id}:${secret}`),
      res
    );
    expect(auth).toBeUndefined();
    expect(res.statusCode).toBe(401);
    // the metadata URL in WWW-Authenticate derives from the real env-driven origin
    expect(String(res.headers["WWW-Authenticate"] ?? "")).toContain("console.test.local");
  });

  it("rejects a wrong secret for an existing key", async () => {
    const { token } = await seedApiKey({ secret: "rightsecret" });
    const res = makeRes();
    const auth = await new AuthChecker(deps().prisma, noopSchedule).requireAccessToken(
      makeReq(`Bearer ${token.id}:wrongsecret`),
      res
    );
    expect(auth).toBeUndefined();
    expect(res.statusCode).toBe(401);
  });
});

// Regression: omitting client_secret_expires_at made openid-client (used by
// Smithery) reject registration outright with
// `"client_secret_expires_at" property must be a number`. RFC 7591 §3.2.1 makes
// it REQUIRED whenever a client_secret is issued; 0 == never expires.
it("register returns an RFC 7591 DCR response", async () => {
  const deps_ = { prisma: deps().prisma, kv: {}, accessTokenTtlSec: 3600, refreshTokenTtlDays: 30 } as any;
  const res = makeRes();
  await new OAuthHandlers(deps_).register(
    makePostReq({ client_name: "Smithery", redirect_uris: ["https://smithery.ai/callback"] }),
    res
  );
  expect(res.statusCode).toBe(201);
  expect(res.body).toMatchObject({
    client_id: expect.any(String),
    client_secret: expect.any(String),
    client_secret_expires_at: 0, // number, not undefined — the actual bug
    client_id_issued_at: expect.any(Number),
    client_name: "Smithery",
    redirect_uris: ["https://smithery.ai/callback"],
  });
  // seconds, not milliseconds — a ms value would be ~1000x too large
  expect(res.body.client_id_issued_at).toBeCloseTo(Date.now() / 1000, -2);
});

import { NextApiRequest, NextApiResponse } from "next";
import { db } from "../../../lib/server/db";
import { z } from "zod";
import { getServerLog } from "../../../lib/server/log";
import { firebase } from "../../../lib/server/firebase-server";
import { credentialsLoginEnabled, githubLoginEnabled, oidcLoginEnabled } from "../../../lib/nextauth.config";
import { UserProfileDbModel } from "../../../prisma/schema";
import { getServerEnv } from "../../../lib/server/serverEnv";

const log = getServerLog("api/auth/check-email");

const CheckEmailRequest = z.object({
  email: z.string().email(),
});

type AuthMethod = {
  type:
    | "firebase-password"
    | "firebase-google"
    | "firebase-github"
    | "nextauth-github"
    | "nextauth-credentials"
    | "nextauth-oidc"
    | "dynamic-oidc"
    | "none";
  oidcProviderId?: string;
  oidcProviderName?: string;
};

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== "POST") {
    return res.status(405).json({ error: "Method not allowed" });
  }

  try {
    const authMethods: AuthMethod[] = [];
    const payload = typeof req.body === "string" ? JSON.parse(req.body) : req.body;
    const { email } = CheckEmailRequest.parse(payload);
    const serverEnv = getServerEnv();
    // First, check if Firebase auth is enabled
    const firebaseEnabled = !!serverEnv.FIREBASE_AUTH;
    const dynamicOidcEnabled = serverEnv.DYNAMIC_OIDC_ENABLED;

    // Check if user exists in database with any login provider
    const existingUsers = await db.prisma().userProfile.findMany({
      where: {
        email: email.toLowerCase(),
      },
    });

    if (dynamicOidcEnabled) {
      authMethods.push(...(await checkDynamicOidcUser(email, existingUsers)));
    }

    if (firebaseEnabled) {
      authMethods.push(...(await checkFirebaseUser(email)));
    } else if (existingUsers.length > 0) {
      // Check for nextauth login providers
      // TODO: we should replace hardcoded login providers with a dynamic list from nextauth config
      for (const existingUser of existingUsers) {
        if (["github", "credentials", "oidc"].includes(existingUser.loginProvider)) {
          authMethods.push({
            type: "nextauth-" + existingUser.loginProvider,
          } as AuthMethod);
        }
      }
    }

    // fallback auth type
    if (firebaseEnabled) {
      authMethods.push({ type: "firebase-google" });
    } else if (credentialsLoginEnabled) {
      authMethods.push({ type: "nextauth-credentials" });
    } else if (githubLoginEnabled) {
      authMethods.push({ type: "nextauth-github" });
    } else if (oidcLoginEnabled) {
      authMethods.push({ type: "nextauth-oidc" });
    } else {
      authMethods.push({ type: "none" });
    }
    //deduplicate auth methods
    const seen = new Set();
    const uniqueAuthMethods = authMethods.filter(am => {
      const key = am.type + (am.oidcProviderId || "");
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
    return res.json(uniqueAuthMethods);
  } catch (error: any) {
    log.atError().withCause(error).log("Error checking email auth method");
    return res.status(500).json({ error: "Internal server error" });
  }
}

async function checkFirebaseUser(email: string): Promise<AuthMethod[]> {
  try {
    const authMethods: AuthMethod[] = [];
    const firebaseUser = await firebase().auth().getUserByEmail(email);
    // Check provider data to determine auth method
    if (firebaseUser.providerData && firebaseUser.providerData.length > 0) {
      const providers = firebaseUser.providerData.map(p => p.providerId);
      if (providers.includes("password")) {
        authMethods.push({ type: "firebase-password" });
      } else if (providers.includes("google.com")) {
        authMethods.push({ type: "firebase-google" });
      } else if (providers.includes("github.com")) {
        authMethods.push({ type: "firebase-github" });
      }
      return authMethods;
    }
  } catch (error: any) {
    // User not found in Firebase, continue to check other methods
    if (error.code !== "auth/user-not-found") {
      log.atError().withCause(error).log("Error checking Firebase user");
    }
  }
  return [];
}

type UserProfileDbModel = z.infer<typeof UserProfileDbModel>;

async function checkDynamicOidcUser(email: string, existingUsers: UserProfileDbModel[]): Promise<AuthMethod[]> {
  const authMethods: AuthMethod[] = [];
  for (const existingUser of existingUsers) {
    if (existingUser.loginProvider.startsWith("dynamic-oidc/")) {
      const providerId = existingUser.loginProvider.split("/")[1];
      if (providerId) {
        const provider = await db.prisma().oidcProvider.findFirst({
          where: { id: providerId, enabled: true },
          select: { id: true, name: true },
        });
        if (provider) {
          authMethods.push({
            type: "dynamic-oidc",
            oidcProviderId: provider.id,
            oidcProviderName: provider.name,
          });
        }
      }
    }
  }

  // Check for dynamic OIDC providers
  const dynamicOidcProviders = await db.prisma().oidcProvider.findMany({
    where: { enabled: true },
    select: {
      id: true,
      name: true,
    },
  });
  if (dynamicOidcProviders.length === 0) {
    return [];
  }
  const invitation = await db.prisma().invitationToken.findFirst({
    where: {
      email: email.toLowerCase(),
      usedBy: null, // Only unused invitations
    },
    orderBy: {
      createdAt: "desc",
    },
  });
  if (invitation) {
    // Check if the workspace has OIDC configured
    const workspace = await db.prisma().workspace.findUnique({
      where: {
        id: invitation.workspaceId,
      },
      include: {
        oidcLoginGroups: {
          include: {
            oidcProvider: true,
          },
        },
      },
    });
    if (workspace && workspace.oidcLoginGroups.length > 0) {
      const oidcGroup = workspace.oidcLoginGroups.find(group => group.oidcProvider.enabled);
      if (oidcGroup) {
        authMethods.push({
          type: "dynamic-oidc",
          oidcProviderId: oidcGroup.oidcProvider.id,
          oidcProviderName: oidcGroup.oidcProvider.name,
        });
      }
    }
  }
  return authMethods;
}

import { createRoute } from "../../../lib/api";
import { z } from "zod";
import { CreateUserResult } from "../../../lib/schema";
import { isPersonalEmailSignupBlocked } from "../../../lib/server/signup-restrictions";
import { WORK_EMAIL_REQUIRED_MESSAGE } from "../../../lib/shared/email-domains";

/**
 * JITSU-70: pre-signup check for the email/password path. The form calls this
 * before creating the Firebase account so a personal-email signup is refused
 * upfront (no account, no verification email) instead of only after the user
 * verifies. The policy + domain list stay server-side; the typed result mirrors
 * create-user. create-user / init-user remain the authoritative backstops.
 */
export default createRoute()
  .POST({
    auth: false,
    // A pure policy check that touches no DB — keep it working during maintenance
    // so the signup form stays responsive.
    allowDuringMaintenance: true,
    body: z.object({ email: z.string() }),
    result: CreateUserResult,
  })
  .handler(async ({ body }) => {
    if (isPersonalEmailSignupBlocked({ email: body.email })) {
      return { ok: false, rejected: "personal-email", message: WORK_EMAIL_REQUIRED_MESSAGE } as const;
    }
    return { ok: true } as const;
  })
  .toNextApiHandler();

/* eslint-disable no-restricted-properties -- this file's job is to WRITE the
   baseline process.env before lib/server modules (serverEnv included) load;
   it cannot go through serverEnv. */
import { afterAll, afterEach, inject } from "vitest";
import { Client } from "pg";
import { createClient } from "@clickhouse/client";
import { randomBytes } from "node:crypto";
import { server, passthroughPrefixes, startMsw } from "./msw";

// Per-test-file setup. Runs in the worker fork BEFORE the test file's module
// graph is imported — that ordering is what makes the harness work: lib/server
// modules snapshot env and build singletons at import time (db.ts freezes
// DATABASE_URL into `global["singletons_*"]` on first import, clickhouse.ts
// builds its client from serverEnv), so everything below must be in place
// before any test file import of lib/** evaluates.
//
// IMPORTANT: no static lib/** imports in this file (the dynamic import below
// runs after the env baseline is set, which is safe).
//
// Isolation model: vitest's forks pool with isolate:true gives every test file
// its own process. This file claims a fresh Postgres database (cloned from the
// template built in global-setup.ts) and a fresh ClickHouse database for that
// process; the env assignments die with the fork, so nothing leaks between
// files. Per-test env overrides inside a file use vi.stubEnv (auto-restored via
// unstubEnvs:true in vitest.config.ts).

const runId = "t" + randomBytes(6).toString("hex");
const pgUrlBase = inject("pgUrlBase");
const chUrl = inject("chUrl");
const pgDb = `console_${runId}`;
const chDb = `metrics_${runId}`;

// A fresh fork has no singletons, but be defensive about juava's global cache.
for (const key of Object.keys(global).filter(k => k.startsWith("singletons_"))) {
  delete (global as any)[key];
}

// Claim Postgres: clone the sealed template (~100–200ms). The advisory lock
// serializes concurrent CREATE DATABASE ... TEMPLATE across parallel forks.
{
  const admin = new Client({ connectionString: inject("pgAdminUrl") });
  await admin.connect();
  try {
    await admin.query("select pg_advisory_lock(4290)");
    try {
      await admin.query(`create database "${pgDb}" template "${inject("pgTemplateDb")}"`);
    } finally {
      await admin.query("select pg_advisory_unlock(4290)");
    }
  } finally {
    await admin.end();
  }
}

// Baseline env. Everything a module-level getServerEnv() snapshot may read must
// be correct here; call-time readers can additionally be overridden per test
// with vi.stubEnv (getServerEnv re-parses per call under vitest — see the
// VITEST check in lib/server/serverEnv.ts).
process.env.DATABASE_URL = `${pgUrlBase}/${pgDb}?schema=newjitsu`;
process.env.CLICKHOUSE_URL = chUrl;
process.env.CLICKHOUSE_DATABASE = chDb;
process.env.CLICKHOUSE_METRICS_SCHEMA = chDb; // getClickhouseConfig prefers this over CLICKHOUSE_DATABASE
// The container runs an unauthenticated `default` user over plain HTTP. A
// developer's root .env.local carries real ClickHouse settings, and
// getClickhouseConfig (libs/juava/src/clickhouse.ts) would send those to the
// container — every ClickHouse-backed test then fails locally with
// "Authentication failed" while CI (no such env) passes. Drop everything the
// harness doesn't set itself, so it is the only source of connection settings.
// Note the reader uses CLICKHOUSE_USERNAME; CLICKHOUSE_USER is a legacy spelling
// that appears in local envs and is cleared for good measure.
for (const v of [
  "CLICKHOUSE_HOST",
  "CLICKHOUSE_USER",
  "CLICKHOUSE_USERNAME",
  "CLICKHOUSE_PASSWORD",
  "CLICKHOUSE_SSL",
]) {
  delete process.env[v];
}
process.env.JWT_SECRET = "test-jwt-secret";
process.env.NEXTAUTH_SECRET = "test-nextauth-secret";
// audit-log.ts snapshots this at import time
process.env.CONSOLE_ENABLE_AUDIT_LOG = "true";
// telemetry.ts snapshots at import time; keep both paths off so no test fires
// telemetry HTTP in the background
process.env.JITSU_DISABLE_ANONYMOUS_TELEMETRY = "1";
delete process.env.JITSU_PRODUCT_TELEMETRY_HOST;
delete process.env.EE_CONNECTION; // isEEAvailable() → false, EE quota checks skipped
// Fake hosts for external services — every request to them must have an MSW handler
process.env.SYNCCTL_URL = "http://syncctl.test.local";
process.env.BULKER_URL = "http://bulker.test.local";
process.env.FUNCTIONS_SERVER_URL_TEMPLATE = "http://fs-${workspaceId}.test.local";
process.env.JITSU_PUBLIC_URL = "http://console.test.local";

// Claim ClickHouse: the same DDL the admin/events-log-init route runs in prod
// (database + events_log/task_log/dead_letter + retention machinery), pointed
// at this file's database. Imported dynamically — env above is already final.
{
  const { initEventsLogTables } = await import("../../../lib/server/clickhouse-init");
  const { initMetricsTables } = await import("../../../lib/server/clickhouse-metrics-init");
  const chAdmin = createClient({ url: chUrl });
  try {
    await initEventsLogTables({ clickhouse: chAdmin, database: chDb, username: "default", password: "" });
    await initMetricsTables({ clickhouse: chAdmin, database: chDb });
  } finally {
    await chAdmin.close();
  }
}

passthroughPrefixes.push(chUrl);
startMsw();
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

/* eslint-disable no-restricted-properties -- runs in the vitest main process,
   outside the app; reads the reuse flag and passes env to the prisma CLI. */
import { GenericContainer, StartedTestContainer, Wait } from "testcontainers";
import { Client } from "pg";
import { createClient } from "@clickhouse/client";
import { execFileSync } from "node:child_process";
import { createRequire } from "node:module";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import * as path from "node:path";
import type { TestProject } from "vitest/node";

// Runs once per `vitest run` (only for the "integration" project): boots Postgres and
// ClickHouse containers, pushes the prisma schema into a sealed template
// database, and hands connection URLs to the worker forks via provide/inject.
// Each test file then clones the template into its own database (see setup.ts).
//
// CONSOLE_TEST_CONTAINERS_REUSE=1 keeps the containers running between local
// runs (testcontainers reuse): the next run connects in ~1s instead of paying
// the ~25s boot + `prisma db push`. The template is keyed by a hash of
// schema.prisma, so a schema change rebuilds it. Trade-off: the containers
// stay up until you `docker rm -f` them. See CONTRIBUTING.md.

const REUSE = process.env.CONSOLE_TEST_CONTAINERS_REUSE === "1";

const PG_IMAGE = "postgres:18-alpine"; // prod runs CNPG 18.x
// Match the oldest supported production cluster so DDL cannot accidentally use
// syntax introduced by a newer ClickHouse release.
const CH_IMAGE = "clickhouse/clickhouse-server:23.8.9.54-alpine";

function templateDbName(root: string): string {
  const schema = readFileSync(path.join(root, "prisma/schema.prisma"));
  return `console_tpl_${createHash("sha256").update(schema).digest("hex").slice(0, 8)}`;
}

export default async function setup(project: TestProject) {
  const root = project.config.root;
  const templateDb = templateDbName(root);

  let pgContainer = new GenericContainer(PG_IMAGE)
    .withEnvironment({ POSTGRES_USER: "jitsu", POSTGRES_PASSWORD: "jitsu", POSTGRES_DB: "postgres" })
    .withExposedPorts(5432)
    .withWaitStrategy(Wait.forLogMessage(/database system is ready to accept connections/, 2))
    .withStartupTimeout(120_000);
  let chContainer = new GenericContainer(CH_IMAGE)
    .withExposedPorts(8123)
    .withEnvironment({
      CLICKHOUSE_DB: "default",
      CLICKHOUSE_USER: "default",
      CLICKHOUSE_DEFAULT_ACCESS_MANAGEMENT: "1",
      CLICKHOUSE_SKIP_USER_SETUP: "1",
    })
    .withWaitStrategy(Wait.forHttp("/ping", 8123).forStatusCode(200))
    .withStartupTimeout(120_000);
  if (REUSE) {
    pgContainer = pgContainer.withReuse();
    chContainer = chContainer.withReuse();
  }

  const [pg, ch]: StartedTestContainer[] = await Promise.all([pgContainer.start(), chContainer.start()]);

  const pgUrlBase = `postgres://jitsu:jitsu@${pg.getHost()}:${pg.getMappedPort(5432)}`;
  const pgAdminUrl = `${pgUrlBase}/postgres`;
  const chUrl = `http://${ch.getHost()}:${ch.getMappedPort(8123)}`;

  const admin = new Client({ connectionString: pgAdminUrl });
  await admin.connect();
  try {
    if (REUSE) {
      await sweepStaleDatabases(admin, chUrl, templateDb);
    }
    const exists = await admin.query(`select 1 from pg_database where datname = $1`, [templateDb]);
    if (exists.rowCount === 0) {
      await admin.query(`create database "${templateDb}"`);
      // prisma has no supported programmatic API for `db push` — spawn the CLI,
      // resolved through the module system (no .bin or node_modules hardcodes).
      const require = createRequire(import.meta.url);
      execFileSync(
        process.execPath,
        [
          require.resolve("prisma/build/index.js"),
          "db",
          "push",
          "--skip-generate",
          `--schema=${path.join(root, "prisma/schema.prisma")}`,
        ],
        {
          env: { ...process.env, DATABASE_URL: `${pgUrlBase}/${templateDb}?schema=newjitsu` },
          stdio: "inherit",
        }
      );
      // Seal the template: CREATE DATABASE ... TEMPLATE requires zero live connections.
      await admin.query(`select pg_terminate_backend(pid) from pg_stat_activity where datname = $1`, [templateDb]);
      await admin.query(`alter database "${templateDb}" with is_template true allow_connections false`);
    }
  } finally {
    await admin.end();
  }

  project.provide("pgUrlBase", pgUrlBase);
  project.provide("pgAdminUrl", pgAdminUrl);
  project.provide("pgTemplateDb", templateDb);
  project.provide("chUrl", chUrl);

  return async () => {
    if (!REUSE) {
      await Promise.all([pg.stop(), ch.stop()]);
    }
  };
}

// Reused containers accumulate per-file databases across runs (each ~the size
// of the schema). Drop leftovers from previous runs, plus templates built from
// older schema.prisma versions.
async function sweepStaleDatabases(admin: Client, chUrl: string, currentTemplate: string) {
  const stale = await admin.query(
    `select datname, datistemplate from pg_database
      where (datname like 'console_t%' and datname != $1)`,
    [currentTemplate]
  );
  for (const row of stale.rows) {
    try {
      if (row.datistemplate) {
        await admin.query(`alter database "${row.datname}" with is_template false`);
      }
      await admin.query(`drop database "${row.datname}" with (force)`);
    } catch (e) {
      console.warn(`test-harness: failed to drop stale database ${row.datname}: ${e}`);
    }
  }
  const chAdmin = createClient({ url: chUrl });
  try {
    const rs = await chAdmin.query({
      query: `select name from system.databases where name like 'metrics_t%'`,
      format: "JSONEachRow",
    });
    for (const row of (await rs.json()) as { name: string }[]) {
      await chAdmin.command({ query: `drop database if exists "${row.name}"` });
    }
  } catch (e) {
    console.warn(`test-harness: ClickHouse stale-database sweep failed: ${e}`);
  } finally {
    await chAdmin.close();
  }
}

import React, { ReactNode, useEffect, useState } from "react";
import { useRouter } from "next/router";
import Link from "next/link";
import { Alert, Button, Input, Spin } from "antd";
import { getErrorMessage } from "juava";
import { SigninLayout } from "../../components/SignInOrUp/SignInOrUp";
import { useFirebaseSession } from "../../lib/firebase-client";

export async function getServerSideProps() {
  return { props: { publicPage: true } };
}

/**
 * Custom Firebase email-action handler. Firebase's `callbackUri` points here, so
 * verification / password-reset / email-recovery links land in the console
 * instead of Firebase's bare hosted page — and we can redirect into the app once
 * the action completes. See JITSU-018.
 */
type ActionState =
  | { status: "working" }
  | { status: "verified" }
  | { status: "recovered" }
  | { status: "reset-form"; email: string }
  | { status: "reset-done" }
  | { status: "error"; message: string };

function explainActionError(e: any): string {
  switch (e?.code) {
    case "auth/expired-action-code":
      return "This link has expired. Request a new email and try again.";
    case "auth/invalid-action-code":
      return "This link is invalid or has already been used.";
    case "auth/user-disabled":
      return "This account has been disabled.";
    case "auth/user-not-found":
      return "No account was found for this link.";
    case "auth/weak-password":
      return "Password is too weak. Use at least 6 characters.";
    default:
      return getErrorMessage(e);
  }
}

const REDIRECT_DELAY_MS = 2500;

const AuthActionPage = () => {
  const router = useRouter();
  const firebaseSession = useFirebaseSession();
  const [state, setState] = useState<ActionState>({ status: "working" });
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  const mode = typeof router.query.mode === "string" ? router.query.mode : undefined;
  const oobCode = typeof router.query.oobCode === "string" ? router.query.oobCode : undefined;

  // Apply the action code once the route query is available.
  useEffect(() => {
    if (!router.isReady) {
      return;
    }
    if (!mode || !oobCode) {
      setState({ status: "error", message: "This link is missing required parameters." });
      return;
    }
    let cancelled = false;
    (async () => {
      try {
        if (mode === "verifyEmail") {
          await firebaseSession.applyActionCode(oobCode);
          if (!cancelled) setState({ status: "verified" });
        } else if (mode === "recoverEmail") {
          await firebaseSession.applyActionCode(oobCode);
          if (!cancelled) setState({ status: "recovered" });
        } else if (mode === "resetPassword") {
          const email = await firebaseSession.verifyPasswordResetCode(oobCode);
          if (!cancelled) setState({ status: "reset-form", email });
        } else {
          if (!cancelled) setState({ status: "error", message: `Unsupported action: ${mode}` });
        }
      } catch (e) {
        if (!cancelled) setState({ status: "error", message: explainActionError(e) });
      }
    })();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [router.isReady, mode, oobCode]);

  // Once the action is done, send the user to sign in.
  useEffect(() => {
    if (state.status === "verified" || state.status === "recovered" || state.status === "reset-done") {
      const t = setTimeout(() => router.replace("/signin"), REDIRECT_DELAY_MS);
      return () => clearTimeout(t);
    }
  }, [state.status, router]);

  const submitNewPassword = async () => {
    if (state.status !== "reset-form" || !oobCode) {
      return;
    }
    if (password.length < 6) {
      setFormError("Password must be at least 6 characters");
      return;
    }
    if (password !== confirm) {
      setFormError("Passwords do not match");
      return;
    }
    setFormError(null);
    setSubmitting(true);
    try {
      await firebaseSession.confirmPasswordReset(oobCode, password);
      setState({ status: "reset-done" });
    } catch (e) {
      setFormError(explainActionError(e));
    } finally {
      setSubmitting(false);
    }
  };

  if (state.status === "working") {
    return (
      <SigninLayout title={<div className="text-2xl">One moment…</div>}>
        <div className="max-w-[350px] flex justify-center py-4">
          <Spin size="large" />
        </div>
      </SigninLayout>
    );
  }

  if (state.status === "reset-form") {
    return (
      <SigninLayout title={<div className="text-2xl">Set a new password</div>}>
        <div className="max-w-[350px]">
          <p className="text-textLight">
            Choose a new password for <span className="font-bold">{state.email}</span>.
          </p>
          <div className="mt-4 space-y-3">
            <Input.Password
              size="large"
              autoFocus
              autoComplete="new-password"
              placeholder="New password (min 6 characters)"
              value={password}
              onChange={e => {
                setPassword(e.target.value);
                setFormError(null);
              }}
            />
            <Input.Password
              size="large"
              autoComplete="new-password"
              placeholder="Confirm new password"
              value={confirm}
              onChange={e => {
                setConfirm(e.target.value);
                setFormError(null);
              }}
              onPressEnter={submitNewPassword}
            />
            {formError && <Alert type="error" message={formError} />}
            <Button block type="primary" size="large" loading={submitting} onClick={submitNewPassword}>
              Update password
            </Button>
          </div>
        </div>
      </SigninLayout>
    );
  }

  const screens: Record<"verified" | "recovered" | "reset-done" | "error", { title: string; body: ReactNode }> = {
    verified: { title: "Email verified", body: "Your email address is verified. Taking you to sign in…" },
    recovered: { title: "Email change reverted", body: "Your sign-in email has been restored. Taking you to sign in…" },
    "reset-done": { title: "Password updated", body: "Your password has been changed. Taking you to sign in…" },
    error: { title: "Link problem", body: state.status === "error" ? state.message : "" },
  };
  const screen = screens[state.status];

  return (
    <SigninLayout
      title={<div className="text-2xl">{screen.title}</div>}
      footer={
        <div className="text-center mt-4">
          <Link className="font-bold text-primary" href="/signin">
            Go to sign in →
          </Link>
        </div>
      }
    >
      <div className="max-w-[350px]">
        {state.status === "error" ? (
          <Alert type="error" message={screen.body} />
        ) : (
          <p className="text-textLight">{screen.body}</p>
        )}
      </div>
    </SigninLayout>
  );
};

