# Connection URLs of the in-cluster dependencies, consumed by the main chart's
# services via `envFrom` (after `jitsu-secrets`, so these win over any legacy
# URL keys there). Explicit env entries in the main chart (env.common.<VAR>)
# take precedence over envFrom, so a disabled dependency here is overridden by
# setting the matching variable in the main chart's values.
apiVersion: v1
kind: Secret
metadata:
  name: jitsu-deps-urls
  labels:
    {{- include "jitsu-deps.labels" . | nindent 4 }}
type: Opaque
stringData:
  {{- if .Values.kafka.enabled }}
  KAFKA_BOOTSTRAP_SERVERS: "kafka:9092"
  {{- end }}
  {{- if .Values.postgres.enabled }}
  # The prisma-style ?schema= parameter is understood by the console (Prisma)
  # and stripped by the Go services' pg pool config, so one URL serves every
  # service.
  DATABASE_URL: "postgresql://postgres:{{ .Values.postgres.password | urlquery }}@postgres:5432/postgres?schema=newjitsu"
  {{- end }}
  {{- if .Values.clickhouse.enabled }}
  CLICKHOUSE_URL: "http://default:{{ .Values.clickhouse.password | urlquery }}@clickhouse:8123/default"
  {{- end }}
  {{- if .Values.mongodb.enabled }}
  MONGODB_URL: "mongodb://admin:{{ .Values.mongodb.password | urlquery }}@mongodb:27017/admin"
  {{- end }}

