import type { NextApiRequest, NextApiResponse } from "next";
import type { PrismaClient } from "@prisma/client";
import type { AuthInfo } from "@modelcontextprotocol/sdk/server/auth/types.js";
import { checkHash } from "juava";
import { getServerLog } from "../log";
import { getPublicOrigin } from "../origin";
import { type FireAndForget, detachedPromise } from "../kv";

const log = getServerLog("mcp-auth");

function bearer(req: NextApiRequest): string | undefined {
  const h = req.headers.authorization;
  if (!h) return undefined;
  const [scheme, token] = h.split(" ", 2);
  return scheme?.toLowerCase() === "bearer" && token ? token : undefined;
}

// Mints a 401 response that points the client at our OAuth metadata
// (per MCP / RFC 9728). Without this header, MCP clients won't know how
// to start the OAuth flow.
function send401(res: NextApiResponse, error: string, description: string) {
  const base = getPublicOrigin();
  res.setHeader(
    "WWW-Authenticate",
    `Bearer realm="jitsu-mcp", error="${error}", error_description="${description}", resource_metadata="${base}/.well-known/oauth-protected-resource"`
  );
  res.status(401).json({ error, error_description: description });
}

export class AuthChecker {
  constructor(private readonly prisma: PrismaClient, private readonly schedule: FireAndForget = detachedPromise) {}

  async requireAccessToken(req: NextApiRequest, res: NextApiResponse): Promise<AuthInfo | undefined> {
    const raw = bearer(req);
    if (!raw) {
      send401(res, "missing_token", "Authorization header either missing or malformed");
      return undefined;
    }
    const [tokenId, secret] = raw.split(":");
    if (!tokenId || !secret) {
      send401(res, "invalid_token", "Token format must be tokenId:secret");
      return undefined;
    }
    // Two auth paths share the `keyId:secret` bearer shape. The OAuth path
    // (interactive clients) is the hot one, so try it first; on a miss, fall
    // back to a personal API key — the same key the management REST API accepts,
    // for CI / headless where the browser OAuth flow can't run.
    const oauth = await this.fromOAuthAccessToken(res, raw, tokenId, secret);
    if (oauth) return oauth;
    // A found-but-invalid OAuth token (bad secret / expired) already sent its
    // 401; only fall through to the API-key path when the id simply wasn't an
    // OAuth access token.
    if (res.headersSent) return undefined;
    return this.fromApiKey(res, raw, tokenId, secret);
  }

  // OAuth path: short-lived OAuthAccessToken minted via the authorize flow.
  // Returns undefined (without sending a response) when no such token exists,
  // so the caller can try the API-key path. A found-but-invalid token (bad
  // secret / expired) sends its own 401 and returns undefined.
  private async fromOAuthAccessToken(
    res: NextApiResponse,
    raw: string,
    tokenId: string,
    secret: string
  ): Promise<AuthInfo | undefined> {
    const at = await this.prisma.oAuthAccessToken.findUnique({
      where: { id: tokenId },
      include: { refreshToken: { include: { user: true, oauthClient: true } } },
    });
    if (!at) return undefined;
    if (!checkHash(at.hash, secret)) {
      send401(res, "invalid_token", "Access token secret mismatch");
      return undefined;
    }
    if (at.expiresAt.getTime() < Date.now()) {
      send401(res, "expired_token", "Access token has expired");
      return undefined;
    }
    this.schedule(async () => {
      const now = new Date();
      await this.prisma.oAuthAccessToken
        .update({ where: { id: at.id }, data: { lastUsed: now } })
        .catch(e => log.atWarn().withCause(e).log("Failed to bump OAuthAccessToken.lastUsed"));
      await this.prisma.userApiToken
        .update({ where: { id: at.refreshTokenId }, data: { lastUsed: now } })
        .catch(e => log.atWarn().withCause(e).log("Failed to bump UserApiToken.lastUsed"));
    });

    const user = at.refreshToken.user;
    return {
      token: raw,
      clientId: at.refreshToken.oauthClientId ?? "unknown",
      scopes: [],
      expiresAt: Math.floor(at.expiresAt.getTime() / 1000),
      extra: {
        userId: user.id,
        email: user.email,
        name: user.name,
        // Carried so tools can build a SessionUser for verifyAccess / audit-log
        // without re-querying UserProfile, and so config-object audit rows are
        // attributed to the MCP token (refreshTokenId) and login identity.
        externalId: user.externalId,
        loginProvider: user.loginProvider,
        refreshTokenId: at.refreshTokenId,
        clientName: at.refreshToken.oauthClient?.name,
      },
    };
  }

  // API-key path: a personal UserApiToken (oauthClientId IS NULL), the same key
  // type the management REST API accepts (see lib/api.ts). Always sends a 401 on
  // failure — it's the last path tried, so an unknown id here means the whole
  // bearer is invalid.
  private async fromApiKey(
    res: NextApiResponse,
    raw: string,
    tokenId: string,
    secret: string
  ): Promise<AuthInfo | undefined> {
    const token = await this.prisma.userApiToken.findUnique({
      where: { id: tokenId },
      include: { user: true },
    });
    if (!token) {
      send401(res, "invalid_token", "Access token not found");
      return undefined;
    }
    // Verify the secret before branching on the token's kind, so a bad secret
    // returns the same error for every id — without this, the oauthClientId
    // check below would be a token-type oracle for callers who don't hold the
    // secret. Matches the check order in lib/api.ts for the REST API.
    if (!checkHash(token.hash, secret)) {
      send401(res, "invalid_token", "Access token secret mismatch");
      return undefined;
    }
    // OAuth refresh tokens live in UserApiToken too, but must not be usable as
    // MCP bearer keys — symmetric to the rejection in lib/api.ts for the REST API.
    if (token.oauthClientId) {
      send401(res, "invalid_token", "OAuth refresh tokens cannot be used as MCP API keys");
      return undefined;
    }
    if (token.expiresAt && token.expiresAt.getTime() < Date.now()) {
      send401(res, "expired_token", "API key has expired");
      return undefined;
    }
    this.schedule(async () => {
      await this.prisma.userApiToken
        .update({ where: { id: token.id }, data: { lastUsed: new Date() } })
        .catch(e => log.atWarn().withCause(e).log("Failed to bump UserApiToken.lastUsed"));
    });

    const user = token.user;
    return {
      token: raw,
      clientId: "api-key",
      scopes: [],
      // No server-side expiry for a non-expiring key; carry the row's expiry if set.
      expiresAt: token.expiresAt ? Math.floor(token.expiresAt.getTime() / 1000) : undefined,
      extra: {
        userId: user.id,
        email: user.email,
        name: user.name,
        externalId: user.externalId,
        loginProvider: user.loginProvider,
        // Attribute audit rows to the API key itself (no OAuth refresh token here).
        refreshTokenId: token.id,
        clientName: token.name ?? undefined,
      },
    };
  }
}

import { Api, inferUrl, nextJsApiHandler } from "../../../lib/api";
import { z } from "zod";
import { firebase } from "../../../lib/server/firebase-server";
import { db } from "../../../lib/server/db";
import { authAuditLog } from "../../../lib/server/audit-log";
import { trackAuthEvent } from "../../../lib/server/telemetry";
import { getServerLog } from "../../../lib/server/log";

const log = getServerLog("firebase-audit-login");

/**
 * Records a Firebase sign-in audit event. Called from the client only at
 * the actual sign-in moment (signIn / signInWith), not from the implicit
 * cookie-mint path used on every page load. Auth is via the supplied
 * idToken in the body — at the call site the user has just authed but
 * may not yet have a session cookie.
 */
export const api: Api = {
  url: inferUrl(__filename),
  POST: {
    auth: false,
    // Called from the client's sign-in flow; failures are swallowed below so
    // a DB write that fails during maintenance won't block login. Allowing
    // the request through means we get a 200 + best-effort audit instead of
    // a confusing 503 on the sign-in path.
    allowDuringMaintenance: true,
    types: {
      body: z.object({ idToken: z.string() }),
    },
    handle: async ({ body, req }) => {
      try {
        const decoded = await firebase().auth().verifyIdToken(body.idToken);
        const email = decoded.email || "";
        let internalId = (decoded as any).internalId as string | undefined;
        if (!internalId && email) {
          const profile = await db
            .prisma()
            .userProfile.findFirst({ where: { externalId: decoded.uid, loginProvider: "firebase" } });
          internalId = profile?.id;
        }
        if (internalId) {
          await authAuditLog({ internalId, email, name: decoded.name || email }, "login", "firebase", undefined, req);
          await trackAuthEvent(
            { internalId, email, name: decoded.name || email, externalId: decoded.uid },
            "login",
            "firebase"
          );
        }
      } catch (err) {
        log
          .atError()
          .withCause(err as Error)
          .log("Failed to record firebase login audit event");
      }
      return { ok: true };
    },
  },
};

export default nextJsApiHandler(api);

import { createRoute } from "../../../lib/api";
import {
  clearLegacyHostAuthCookie,
  firebaseAuthCookieName,
  getAuthCookieDomain,
  signOut,
} from "../../../lib/server/firebase-server";
import { serialize } from "cookie";
import { getAppEndpoint } from "../../../lib/domains";
import { getServerLog } from "../../../lib/server/log";
import { authAuditLog } from "../../../lib/server/audit-log";
import { trackAuthEvent } from "../../../lib/server/telemetry";

const log = getServerLog("firebase");

export default createRoute()
  .GET({ auth: true })
  .handler(async ({ req, body, res, user }) => {
    await signOut(user.externalId);
    try {
      await authAuditLog(
        { internalId: user.internalId, email: user.email, name: user.name },
        "logout",
        "firebase",
        undefined,
        req
      );
      await trackAuthEvent(
        { internalId: user.internalId, email: user.email, name: user.name, externalId: user.externalId },
        "logout",
        "firebase"
      );
    } catch (err) {
      log
        .atError()
        .withCause(err as Error)
        .log("Failed to record firebase logout audit event");
    }
    const secure = getAppEndpoint(req).protocol === "https";
    // Name, path and domain must all match create-session, or the real cookie
    // won't be cleared.
    const domain = getAuthCookieDomain(req);
    const clearCookies = [
      serialize(firebaseAuthCookieName, "", {
        maxAge: 0,
        httpOnly: true,
        secure,
        path: "/",
        ...(domain ? { domain } : {}),
      }),
    ];
    // When AUTH_COOKIE_DOMAIN is set, also clear any legacy host-scoped
    // (Domain=<request host>) copy from pre-AUTH_COOKIE_DOMAIN builds, which the
    // parent-domain clear above misses. No-op when AUTH_COOKIE_DOMAIN is unset.
    const legacyClear = clearLegacyHostAuthCookie(req, { secure });
    if (legacyClear) {
      clearCookies.push(legacyClear);
    }
    res.setHeader("Set-Cookie", clearCookies);
  })
  .toNextApiHandler();

import * as crypto from "node:crypto";
import type { NextApiRequest, NextApiResponse } from "next";
import type { OAuthClient, Prisma, PrismaClient } from "@prisma/client";
import { checkHash, createHash, hint, randomId } from "juava";
import { z } from "zod";
import { getServerLog } from "../log";
import { getClientIp, getPublicOrigin } from "../origin";
import { getUser } from "../../api";
import type { KvStore } from "../kv";
import { getRateLimiter, setRateLimitHeaders } from "../rate-limit";
import { getServerEnv } from "../serverEnv";
import { OAuthClientsRepo } from "./clients";
import { OAuthCodesRepo } from "./codes";

const log = getServerLog("oauth");

export interface OAuthHandlersDeps {
  prisma: PrismaClient;
  kv: KvStore;
  accessTokenTtlSec: number;
  refreshTokenTtlDays: number;
}

const RegisterBody = z.object({
  client_name: z.string().min(1).max(200),
  redirect_uris: z.array(z.string().url()).min(1).max(10),
});

const ApproveBody = z.object({
  client_id: z.string(),
  redirect_uri: z.string().url(),
  code_challenge: z.string().min(1),
  code_challenge_method: z.literal("S256"),
  state: z.string().optional(),
  response_type: z.literal("code"),
});

const DenyBody = z.object({
  client_id: z.string(),
  redirect_uri: z.string().url(),
  state: z.string().optional(),
});

// We accept both https: and http: redirect URIs. Restricting http: to loopback
// only (RFC 8252 §8.3) is the ideal, but WHATWG URL returns bracketed IPv6
// hostnames (e.g. "[::1]") making the check fiddly without a dedicated library.
// In practice every MCP client uses a loopback callback anyway, and the real
// security gate is the registered redirect_uri whitelist checked below.
function isSafeRedirectUri(uri: string): boolean {
  try {
    const { protocol } = new URL(uri);
    return protocol === "https:" || protocol === "http:";
  } catch {
    return false;
  }
}

const TokenBodyAuthCode = z.object({
  grant_type: z.literal("authorization_code"),
  code: z.string(),
  redirect_uri: z.string().url(),
  code_verifier: z.string().min(43).max(128), // PKCE spec range
  client_id: z.string(),
  client_secret: z.string(),
});

const TokenBodyRefresh = z.object({
  grant_type: z.literal("refresh_token"),
  refresh_token: z.string(), // "<tokenId>:<secret>" format
  client_id: z.string(),
  client_secret: z.string(),
});

const TokenBody = z.discriminatedUnion("grant_type", [TokenBodyAuthCode, TokenBodyRefresh]);

function verifyPkceS256(verifier: string, challenge: string): boolean {
  const hash = crypto.createHash("sha256").update(verifier).digest("base64url");
  return hash === challenge;
}

function jsonError(res: NextApiResponse, status: number, error: string, description?: string) {
  res.status(status).json({ error, ...(description ? { error_description: description } : {}) });
}

// Parses x-www-form-urlencoded or JSON. Next.js parses both into req.body by
// default, but req.body for form-encoded is a Record<string,string>.
function readBody(req: NextApiRequest): Record<string, unknown> {
  return (req.body as Record<string, unknown>) ?? {};
}

export class OAuthHandlers {
  private readonly clients: OAuthClientsRepo;
  private readonly codes: OAuthCodesRepo;

  constructor(private readonly deps: OAuthHandlersDeps) {
    this.clients = new OAuthClientsRepo(deps.prisma);
    this.codes = new OAuthCodesRepo(deps.kv);
  }

  // ─── Discovery: RFC 8414 ────────────────────────────────────────────────
  authServerMetadata = async (_req: NextApiRequest, res: NextApiResponse) => {
    const base = getPublicOrigin();
    res.status(200).json({
      issuer: base,
      authorization_endpoint: `${base}/oauth/authorize`,
      token_endpoint: `${base}/oauth/token`,
      registration_endpoint: `${base}/oauth/register`,
      response_types_supported: ["code"],
      grant_types_supported: ["authorization_code", "refresh_token"],
      code_challenge_methods_supported: ["S256"],
      token_endpoint_auth_methods_supported: ["client_secret_post"],
      scopes_supported: [],
    });
  };

  // ─── Discovery: RFC 9728 (MCP-required) ─────────────────────────────────
  protectedResourceMetadata = async (_req: NextApiRequest, res: NextApiResponse) => {
    const base = getPublicOrigin();
    res.status(200).json({
      resource: base,
      authorization_servers: [base],
      bearer_methods_supported: ["header"],
    });
  };

  // ─── DCR: RFC 7591 ──────────────────────────────────────────────────────
  register = async (req: NextApiRequest, res: NextApiResponse) => {
    if (req.method !== "POST") return jsonError(res, 405, "method_not_allowed");

    if (getServerEnv().MINUTE_RATE_LIMIT_ENABLED) {
      const ip = getClientIp(req);
      const rl = await getRateLimiter().check({
        authClass: "ip",
        principal: ip,
        method: "POST",
        bucket: "dcr",
        limit: 200,
        windowMs: 60 * 60_000, // 200 registrations per hour per IP
      });
      setRateLimitHeaders(res, rl);
      if (!rl.allowed) {
        res.setHeader("Retry-After", String(rl.retryAfterSec));
        return jsonError(res, 429, "too_many_requests", "Registration rate limit exceeded. Try again later.");
      }
    }

    const parsed = RegisterBody.safeParse(readBody(req));
    if (!parsed.success) {
      return jsonError(res, 400, "invalid_client_metadata", parsed.error.message);
    }
    // Reject dangerous schemes at registration time so they never enter the
    // whitelist in the first place. Defense in depth — approve/deny also
    // re-check the scheme.
    for (const uri of parsed.data.redirect_uris) {
      if (!isSafeRedirectUri(uri)) {
        return jsonError(res, 400, "invalid_redirect_uri", `unsupported scheme: ${uri}`);
      }
    }
    try {
      const c = await this.clients.register(parsed.data.client_name, parsed.data.redirect_uris);
      // RFC 7591 response shape.
      res.status(201).json({
        client_id: c.clientId,
        client_secret: c.clientSecret,
        // RFC 7591 §3.2.1: client_secret_expires_at is REQUIRED whenever a
        // client_secret is issued, and 0 means "never expires" (ours don't).
        // Omitting it makes strict clients (openid-client, used by Smithery)
        // reject the whole registration with
        // `"client_secret_expires_at" property must be a number`.
        client_id_issued_at: Math.floor(c.createdAt.getTime() / 1000),
        client_secret_expires_at: 0,
        client_name: c.name,
        redirect_uris: c.redirectUris,
        token_endpoint_auth_method: "client_secret_post",
        grant_types: ["authorization_code", "refresh_token"],
        response_types: ["code"],
      });
    } catch (e: any) {
      log.atWarn().withCause(e).log("DCR failed");
      jsonError(res, 400, "invalid_client_metadata", e.message ?? "registration failed");
    }
  };

  // ─── Authorize approval (called from the consent page) ──────────────────
  // The consent page (pages/oauth/authorize.tsx) renders the UI and, on
  // Approve, POSTs here. We mint a one-shot code and return the redirect URL
  // the page should send the browser to. We don't 302 directly because the
  // page wants to render a brief "Redirecting..." state.
  approve = async (req: NextApiRequest, res: NextApiResponse) => {
    if (req.method !== "POST") return jsonError(res, 405, "method_not_allowed");
    const sessionUser = await getUser(res, req);
    if (!sessionUser) return jsonError(res, 401, "unauthenticated");
    const parsed = ApproveBody.safeParse(readBody(req));
    if (!parsed.success) {
      return jsonError(res, 400, "invalid_request", parsed.error.message);
    }
    const { client_id, redirect_uri, code_challenge, code_challenge_method, state } = parsed.data;
    const target = await this.resolveRedirectTarget(client_id, redirect_uri);
    if ("error" in target) return jsonError(res, 400, target.error, target.description);
    const code = await this.codes.issueCode({
      clientId: target.client.id,
      userId: sessionUser.internalId,
      redirectUri: target.redirectUri,
      codeChallenge: code_challenge,
      codeChallengeMethod: code_challenge_method,
    });
    const url = new URL(target.redirectUri);
    url.searchParams.set("code", code);
    if (state) url.searchParams.set("state", state);
    res.status(200).json({ redirect_to: url.toString() });
  };

  // Symmetric to approve: same server-side validation, no code issued. The
  // browser used to build this redirect itself from query params — that was
  // an open redirect because nothing checked the redirect_uri was registered
  // for the client. Always route deny through the server.
  deny = async (req: NextApiRequest, res: NextApiResponse) => {
    if (req.method !== "POST") return jsonError(res, 405, "method_not_allowed");
    const parsed = DenyBody.safeParse(readBody(req));
    if (!parsed.success) {
      return jsonError(res, 400, "invalid_request", parsed.error.message);
    }
    const { client_id, redirect_uri, state } = parsed.data;
    const target = await this.resolveRedirectTarget(client_id, redirect_uri);
    if ("error" in target) return jsonError(res, 400, target.error, target.description);
    const url = new URL(target.redirectUri);
    url.searchParams.set("error", "access_denied");
    if (state) url.searchParams.set("state", state);
    res.status(200).json({ redirect_to: url.toString() });
  };

  // Shared validation: client must exist, redirect_uri must be in its
  // registered whitelist, and the scheme must be http/https. Either side
  // (approve, deny) calls this before bouncing the browser anywhere.
  private async resolveRedirectTarget(
    clientId: string,
    redirectUri: string
  ): Promise<
    { client: { id: string; redirectUris: string[] }; redirectUri: string } | { error: string; description: string }
  > {
    if (!isSafeRedirectUri(redirectUri)) {
      return { error: "invalid_request", description: "unsafe redirect_uri scheme" };
    }
    const client = await this.clients.findById(clientId);
    if (!client) return { error: "invalid_client", description: "unknown client_id" };
    if (!client.redirectUris.includes(redirectUri)) {
      return { error: "invalid_request", description: "redirect_uri not registered for this client" };
    }
    return { client, redirectUri };
  }

  // ─── Token endpoint: handles both grants ────────────────────────────────
  token = async (req: NextApiRequest, res: NextApiResponse) => {
    if (req.method !== "POST") return jsonError(res, 405, "method_not_allowed");
    const parsed = TokenBody.safeParse(readBody(req));
    if (!parsed.success) {
      return jsonError(res, 400, "invalid_request", parsed.error.message);
    }
    if (parsed.data.grant_type === "authorization_code") {
      return this.tokenFromCode(parsed.data, res);
    }
    return this.tokenFromRefresh(parsed.data, res);
  };

  private async tokenFromCode(body: z.infer<typeof TokenBodyAuthCode>, res: NextApiResponse): Promise<void> {
    const client = await this.clients.verifyCredentials(body.client_id, body.client_secret);
    if (!client) return jsonError(res, 401, "invalid_client");

    const codePayload = await this.codes.consumeCode(body.code);
    if (!codePayload) return jsonError(res, 400, "invalid_grant", "code expired or already used");
    if (codePayload.clientId !== client.id) {
      return jsonError(res, 400, "invalid_grant", "code does not belong to client");
    }
    if (codePayload.redirectUri !== body.redirect_uri) {
      return jsonError(res, 400, "invalid_grant", "redirect_uri mismatch");
    }
    if (!verifyPkceS256(body.code_verifier, codePayload.codeChallenge)) {
      return jsonError(res, 400, "invalid_grant", "PKCE verification failed");
    }

    // 1:1 enforcement: drop any prior refresh tokens (+ their access tokens)
    // for this user+client. Advisory lock serializes concurrent code exchanges
    // for the same user+client so both can't see prior=[] and both create tokens.
    const issued = await this.deps.prisma.$transaction(async tx => {
      await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${client.id + ":" + codePayload.userId}))`;
      const prior = await tx.userApiToken.findMany({
        where: { oauthClientId: client.id, userId: codePayload.userId },
        select: { id: true },
      });
      if (prior.length) {
        await tx.oAuthAccessToken.deleteMany({
          where: { refreshTokenId: { in: prior.map(t => t.id) } },
        });
        await tx.userApiToken.deleteMany({ where: { id: { in: prior.map(t => t.id) } } });
      }
      return this.createTokenPair(tx, client, codePayload.userId);
    });

    res.status(200).json(issued);
  }

  private async tokenFromRefresh(body: z.infer<typeof TokenBodyRefresh>, res: NextApiResponse): Promise<void> {
    const client = await this.clients.verifyCredentials(body.client_id, body.client_secret);
    if (!client) return jsonError(res, 401, "invalid_client");

    const [refreshId, refreshSecret] = body.refresh_token.split(":");
    if (!refreshId || !refreshSecret) {
      return jsonError(res, 400, "invalid_grant", "malformed refresh_token");
    }
    const refresh = await this.deps.prisma.userApiToken.findUnique({ where: { id: refreshId } });
    if (!refresh || refresh.oauthClientId !== client.id) {
      return jsonError(res, 400, "invalid_grant", "refresh token unknown for this client");
    }
    if (refresh.expiresAt && refresh.expiresAt.getTime() < Date.now()) {
      return jsonError(res, 400, "invalid_grant", "refresh token expired");
    }
    if (!checkHash(refresh.hash, refreshSecret)) {
      return jsonError(res, 400, "invalid_grant", "refresh token secret mismatch");
    }

    // Rotation: replace the secret on the same row (id stays so /user UI is
    // stable). CAS on the current hash prevents two concurrent rotations both
    // succeeding — the second updateMany sees count=0 and we return null.
    const newRefreshSecret = randomId({ digits: 48, strongRandom: true });
    const newExpiresAt = new Date(Date.now() + this.deps.refreshTokenTtlDays * 86400 * 1000);
    const issued = await this.deps.prisma.$transaction(async tx => {
      const rotated = await tx.userApiToken.updateMany({
        where: { id: refresh.id, hash: refresh.hash },
        data: { hash: createHash(newRefreshSecret), expiresAt: newExpiresAt, lastUsed: new Date() },
      });
      if (rotated.count === 0) return null; // concurrent rotation already consumed this token
      await tx.oAuthAccessToken.deleteMany({ where: { refreshTokenId: refresh.id } });
      const accessSecret = randomId({ digits: 48, strongRandom: true });
      const accessExpires = new Date(Date.now() + this.deps.accessTokenTtlSec * 1000);
      const access = await tx.oAuthAccessToken.create({
        data: { hash: createHash(accessSecret), expiresAt: accessExpires, refreshTokenId: refresh.id },
      });
      return {
        access_token: `${access.id}:${accessSecret}`,
        refresh_token: `${refresh.id}:${newRefreshSecret}`,
        token_type: "Bearer" as const,
        expires_in: this.deps.accessTokenTtlSec,
      };
    });
    if (!issued) return jsonError(res, 400, "invalid_grant", "refresh token already rotated, please retry");
    res.status(200).json(issued);
  }

  // Shared between fresh authorize and (in theory) future grant types.
  private async createTokenPair(tx: Prisma.TransactionClient, client: OAuthClient, userId: string) {
    const refreshSecret = randomId({ digits: 48, strongRandom: true });
    const refreshExpiresAt = new Date(Date.now() + this.deps.refreshTokenTtlDays * 86400 * 1000);
    const refresh = await tx.userApiToken.create({
      data: {
        userId,
        hash: createHash(refreshSecret),
        hint: hint(refreshSecret),
        name: client.name,
        oauthClientId: client.id,
        expiresAt: refreshExpiresAt,
      },
    });
    const accessSecret = randomId({ digits: 48, strongRandom: true });
    const accessExpiresAt = new Date(Date.now() + this.deps.accessTokenTtlSec * 1000);
    const access = await tx.oAuthAccessToken.create({
      data: {
        hash: createHash(accessSecret),
        expiresAt: accessExpiresAt,
        refreshTokenId: refresh.id,
      },
    });
    return {
      access_token: `${access.id}:${accessSecret}`,
      refresh_token: `${refresh.id}:${refreshSecret}`,
      token_type: "Bearer" as const,
      expires_in: this.deps.accessTokenTtlSec,
    };
  }

  // Called from the DELETE /api/user/keys handler for every key delete.
  // For non-MCP tokens (oauthClientId null) this is a plain delete; for MCP
  // tokens it also nukes the access tokens and the OAuthClient row, in the
  // correct order to satisfy FKs. One method = one place to read = one
  // place to update when the model changes.
  deleteUserApiTokenWithMcpCascade = async (refreshTokenId: string): Promise<void> => {
    await this.deps.prisma.$transaction(async tx => {
      const token = await tx.userApiToken.findUnique({
        where: { id: refreshTokenId },
        select: { id: true, oauthClientId: true },
      });
      if (!token) return;
      if (token.oauthClientId) {
        // Order matters: access tokens FK → UserApiToken; UserApiToken FK → OAuthClient.
        await tx.oAuthAccessToken.deleteMany({ where: { refreshTokenId: token.id } });
        await tx.userApiToken.delete({ where: { id: token.id } });
        // Guarded delete: remove the OAuthClient only when no UserApiToken rows
        // still reference it. A plain count-then-delete races with concurrent
        // token issuance, so we use a single DELETE ... WHERE NOT EXISTS to make
        // it atomic. Prisma doesn't support subquery filters, so raw SQL here.
        await tx.$executeRaw`
          DELETE FROM "OAuthClient"
          WHERE id = ${token.oauthClientId}
            AND NOT EXISTS (
              SELECT 1 FROM "UserApiToken"
              WHERE "oauthClientId" = ${token.oauthClientId}
            )`;
      } else {
        await tx.userApiToken.delete({ where: { id: token.id } });
      }
    });
  };
}

import { Api, inferUrl, nextJsApiHandler } from "../../../lib/api";
import { z } from "zod";
import {
  clearLegacyHostAuthCookie,
  createSessionCookie,
  firebase,
  firebaseAuthCookieName,
  getAuthCookieDomain,
  isUnverifiedPasswordAccount,
} from "../../../lib/server/firebase-server";
import { ApiError } from "../../../lib/shared/errors";
import { SerializeOptions, serialize } from "cookie";
import { getAppEndpoint } from "../../../lib/domains";
import { getServerLog } from "../../../lib/server/log";

const log = getServerLog("firebase");

export const api: Api = {
  url: inferUrl(__filename),
  POST: {
    auth: false,
    // Minting a session cookie from a Firebase ID token does not touch the
    // console DB — keep sign-in working during maintenance so operators
    // aren't locked out while toggling things.
    allowDuringMaintenance: true,
    types: {
      body: z.object({
        csrfToken: z.string(),
        idToken: z.string(),
      }),
    },
    handle: async ({ req, body, res }) => {
      const { csrfToken, idToken } = body;
      const secure = getAppEndpoint(req).protocol === "https";
      const csrfCookie = req.cookies["fb-csrfToken"];
      if (csrfToken !== csrfCookie) {
        log
          .atError()
          .log(`CSRF cookie (${csrfCookie}) doesn't match provided token ${csrfToken}`, JSON.stringify(req.cookies));
        throw new ApiError("CSRF error", { status: 401 });
      }
      // JITSU-018: never mint a session cookie for an unverified email+password
      // account, even if the client-side gate was bypassed.
      const decodedIdToken = await firebase().auth().verifyIdToken(idToken);
      if (isUnverifiedPasswordAccount(decodedIdToken)) {
        throw new ApiError("Email address is not verified", { status: 403 });
      }
      const { cookie, expiresIn } = await createSessionCookie(idToken);

      // Audit logging lives in /api/fb-auth/audit-login which the client
      // calls only at the actual sign-in moment. This endpoint is hit on
      // every cookie mint / refresh — too noisy to audit here.

      // Default: Domain=<request host> (shared with that host's subdomains).
      // AUTH_COOKIE_DOMAIN widens it to a parent domain so sibling subdomains
      // share the session. Falls back to host-only only for unparseable hosts.
      const domain = getAuthCookieDomain(req);
      // Never log the cookie value itself — it's a bearer session credential.
      log.atDebug().log(`Setting firebase auth cookie (domain: ${domain ?? "host-only"}, maxAge: ${expiresIn}ms)`);
      const options: SerializeOptions = {
        maxAge: expiresIn,
        httpOnly: true,
        secure,
        path: "/",
        sameSite: "lax",
        // Omit Domain entirely only when the host can't be parsed (host-only).
        ...(domain ? { domain } : {}),
      };
      // When AUTH_COOKIE_DOMAIN is set, also evict any legacy host-scoped
      // (Domain=<request host>) copy left by pre-AUTH_COOKIE_DOMAIN builds;
      // otherwise it lingers and is sent ahead of this fresh parent-domain
      // cookie, keeping the user stuck on the stale 401. No-op when unset.
      const setCookies = [serialize(firebaseAuthCookieName, cookie, options)];
      const legacyClear = clearLegacyHostAuthCookie(req, { secure });
      if (legacyClear) {
        setCookies.push(legacyClear);
      }
      res.setHeader("Set-Cookie", setCookies);

      return { ok: true };
    },
  },
};

export default nextJsApiHandler(api);

import type { NextApiRequest, NextApiResponse } from "next";
import { mcpServer } from "../../../../lib/server/mcp-server";

export default (req: NextApiRequest, res: NextApiResponse) => mcpServer.handleDeny(req, res);
